def safe_divide(a, b):
    try:
        result = a / b
    except ZeroDivisionError as e:
        print(f'Error: {e}')
        return None
    else:
        print('Division succeeded')
        return result
    finally:
        print('Attempt finished')

print(safe_divide(10, 2))
print(safe_divide(10, 0))
